import json

def moves(n, src, dst, aux):
    if n==0: return []
    return moves(n-1, src, aux, dst) + [[n, src, dst]] + moves(n-1, aux, dst, src)
seq=moves(8,0,2,1)
# split into chunks of 25
chunks = [seq[i:i+25] for i in range(0,len(seq),25)]
for i,ch in enumerate(chunks):
    print(f'Chunk {i+1}/{len(chunks)}:')
    print(json.dumps(ch))
